    const value=args[arg.name];
    if(value===undefined){
      if(arg.required){const err=new Error('Missing required argument: '+arg.name);err.code=-32602;throw err}
      continue;
    }
    if(typeof value!=='string'){const err=new Error('Argument must be a string: '+arg.name);err.code=-32602;throw err}
